//! `wisp.rs`: one documented `pub mod` per component, including its
//! generated file, and one per subdirectory.

use std::fmt::Write;
use std::path::Path;

use super::tree::Dir;

/// The modules file for the tree whose generated files are under `generated`.
pub(crate) fn render(tree: &Dir, generated: &Path) -> String {
    let mut text = String::from(
        "// Generated by vapors-compiler from the .wisp files; edit those, not this file.\n",
    );
    render_dir(tree, generated, &mut text);
    text
}

fn render_dir(dir: &Dir, generated: &Path, text: &mut String) {
    for file in &dir.files {
        let include = generated.join(format!("{}.rs", file.module));
        let _ = write!(
            text,
            "\n/// The component compiled from `{}`.\npub mod {} {{\n    include!({:?});\n}}\n",
            file.path.display(),
            file.module,
            include.display().to_string()
        );
    }
    for sub in &dir.dirs {
        let _ = write!(
            text,
            "\n/// The components under `{}`.\npub mod {} {{\n",
            sub.path.display(),
            sub.module
        );
        render_dir(sub, &generated.join(&sub.module), text);
        text.push_str("}\n");
    }
}
